local IdConcatTable = {0, "_", 0}

local function IdConcat(left, right)
    IdConcatTable[1] = left  or 0
    IdConcatTable[3] = right or 0
    return table.concat(IdConcatTable)
end

local function strWalk(str, pattern, walkFunc)
    if string.isEmpty(str) then
       return
    end
    local pos = 0
    local i = 0
    local j = 0
    local strFind = string.find
    local strSub  = string.sub
    while true do
        i,j = strFind(str, pattern, i+1)    -- find 'next' newline
        if i == nil then 
            if pos == 0 then
                walkFunc(str)
            elseif pos > 0 then
                walkFunc(strSub(str, pos))
            end
            break 
        end
        if i > pos and i > 1 then
            walkFunc(strSub(str, pos, i-1))
        end
        pos = j + 1
        walkFunc(strSub(str, i, j), true)
    end
end

--- InitSkills
---@param cardVo CardVo
---@param awakeningLevel number
---@return table[]
function CardProgressionSkillUtils.InitSkills(cardVo, awakeningLevel, finalSkillLevel)
    local skillNode      = cardVo.skillNode
    local SkillGroupType = CardProgressionConstants.SkillGroupType
    local cardId         = cardVo.roleId
    
    local openAbility = CardProgressionSkillUtils.GetTalentId(cardId, awakeningLevel)
    local skills = {
        { skillNode.finalSkill,      finalSkillLevel,   SkillGroupType.Final  },
        { skillNode.generalSkill,    1,                 SkillGroupType.Normal },
        { skillNode.advancedSkill,   1,                 SkillGroupType.Normal },
        { openAbility,               awakeningLevel,    SkillGroupType.Buff   },
    }

    return skills
end

function CardProgressionSkillUtils.GetSkillDescBySkillData(skillData, isSpecify, rare, isAll)
    local skillId, skillLevel, skillGroupType = SafeUnpack(skillData)
    return CardProgressionSkillUtils.GetSkillInfo(skillId, skillLevel, skillGroupType, isSpecify, rare, isAll)
end

function CardProgressionSkillUtils.GetSkillInfo(skillId, skillLevel, skillGroupType, isSpecify, rare, isAll, spDescId, isFull, customDesc)
    ---@type TalentVo | SkillCardVo
    local vo = CardProgressionSkillUtils.GetSkillVoBySkillGroupType(skillId, skillGroupType)
    local desc, name
    if skillGroupType == CardProgressionConstants.SkillGroupType.Final then
        local openLevel     = skillLevel
        local customDesc
        if spDescId then
            customDesc = cardConfMgr:GetStarFinalSkillDescription(spDescId)
        end
        local curSkillStar = not isFull and openLevel or nil
        local skillDescInfo = CardProgressionSkillUtils.ParseSkillDesc(vo, openLevel, true, curSkillStar, isSpecify, rare, isAll, customDesc)
        desc, name = skillDescInfo[openLevel] or skillDescInfo[1], vo.skillName
    elseif skillGroupType == CardProgressionConstants.SkillGroupType.Normal then
        local skillDescInfo = CardProgressionSkillUtils.ParseSkillDesc(vo, skillLevel, false, nil, isSpecify)
        desc, name = skillDescInfo[isAll and 1 or skillLevel], vo.skillName
    elseif skillGroupType == CardProgressionConstants.SkillGroupType.Buff then
        desc, name = CardProgressionSkillUtils.GetCardTalentDesc(vo, skillLevel, nil, customDesc), vo.name

    end
    return desc, name, vo
end

