---ParseSkillDesc
---解析技能描述
---@param skillCardVo    SkillCardVo  技能牌逻辑表vo
---@param skillStar      number                技能星级
---@param isFinal        boolean               是否是大招
---@param curSkillStar   number                当前技能星级
function CardProgressionSkillUtils.ParseSkillDesc(skillCardVo, skillStar, isFinal, curSkillStar, isSpecial, rare, isAll, customDesc, finalSkillLevel)
    rare = rare or 1
    local startSkillStar, endSkillStar = 1, 1
    if isAll then
        startSkillStar = isFinal and 1 or 1
        endSkillStar   = isFinal and cardConfMgr:GetMaxFinalSkillLv() or #skillCardVo.orginSkills
        customDesc     = nil
    elseif skillStar then
        --- 大招不显示全部描述 要取第一个描述
        startSkillStar = isFinal and (curSkillStar or 1) or skillStar
        endSkillStar   = isFinal and (curSkillStar or 1) or skillStar
    end

    local specifyFinalSkillLevel = isNotNull(finalSkillLevel)
    local format = string.format
    local skillDescInfo = {}
    for star = startSkillStar, endSkillStar do
        local skillDesc = customDesc or skillCardVo[format(isSpecial and "specialDesc_%s" or  "skillDesc_%s", star)]
        local finalSkillStar = isAll and star or skillStar
        if not specifyFinalSkillLevel then
            finalSkillLevel = isFinal and CardProgressionSkillUtils.ConvertFinalSkillLvByRare(rare, finalSkillStar) or 0
        end
        --- 大招是1星数据 * 大招系数
        -- local realStar  = isFinal and 1 or star
        local realStar  = star
        local isHideColor = curSkillStar ~= nil and checkNumber(curSkillStar) < star
        skillDesc = CardProgressionSkillUtils.GetStarDesc(skillCardVo, skillDesc, realStar, curSkillStar, finalSkillLevel, skillCardVo, isHideColor, isFinal)
        skillDescInfo[star] = skillDesc

    end

    return skillDescInfo
end

---GetStarDesc
---@param skill           number  技能牌逻辑表vo
---@param skillDesc       string       技能描述
---@param star            number       技能星级
---@param curSkillStar    number       当前技能星级
---@param finalSkillLevel number       大招等级
function CardProgressionSkillUtils.GetStarDescBySkillId(skillId, skillDesc, star, isFinal, curSkillStar, finalSkillLevel, lastSkillId)
    ---@type SkillCardVo
    local vo = CardProgressionSkillUtils.GetSkillVoBySkillGroupType(skillId, isFinal and CardProgressionConstants.SkillGroupType.Final or CardProgressionConstants.SkillGroupType.Normal)
    
    ---@type SkillCardVo
    local lastVo
    if lastSkillId then
        lastVo = CardProgressionSkillUtils.GetSkillVoBySkillGroupType(lastSkillId, isFinal and CardProgressionConstants.SkillGroupType.Final or CardProgressionConstants.SkillGroupType.Normal)
    end
    
    local realVo = vo
    local desc = CardProgressionSkillUtils.GetStarDesc(vo, skillDesc, star, curSkillStar, finalSkillLevel, lastVo, false, isFinal)
    return desc, realVo.skillName
end

---GetStarDesc
---@param skillCardVo     SkillCardVo  技能表vo
---@param skillDesc       string       技能描述
---@param star            number       技能星级
---@param curSkillStar    number       当前技能星级
---@param finalSkillLevel number       大招等级
---@param lastSkillCardVo SkillCardVo  上一技能表vo
function CardProgressionSkillUtils.GetStarDesc(skillCardVo, skillDesc, star, curSkillStar, finalSkillLevel, lastSkillCardVo, isHideColor, isFinal)
    if skillDesc and skillDesc == '0' then
        return skillDesc
    end
    local starDescList = CardProgressionSkillUtils.GetStarDescList(skillCardVo, skillDesc, star, curSkillStar, finalSkillLevel, lastSkillCardVo, isHideColor, isFinal)
    
    if CardProgressionSkillUtils.SkillExtraMode then
        skillDesc = table.concat(starDescList)
    else
        skillDesc = string.gsub(table.concat(starDescList), "\\n", "\n")
    end

    if GameUtils.IsEnableNonBreakingSpace() then
        skillDesc = string.gsub(skillDesc, Space, NonBreakingSpace)
    end

    return skillDesc
end

--- GetStarDescList
---@param skillCardVo SkillCardVo      技能表vo
---@param skillDesc string             技能描述
---@param star number                  技能星级
---@param curSkillStar number          当前技能星级
---@param finalSkillLevel number       大招等级
---@param lastSkillCardVo? SkillCardVo  上一技能表vo
---@param isFinal? boolean 是否是大招
function CardProgressionSkillUtils.GetStarDescList(skillCardVo, skillDesc, star, curSkillStar, finalSkillLevel, lastSkillCardVo, isHideColor, isFinal)
    local paramsCount = 0
    local starDescList = {}
    
    --- 获取由"_"分割后的数据
    local descList = string.split2(skillDesc, "_")
    -- print("descList", table.toString(descList))
    -- print("skillDesc", skillDesc)
    
    local SafeUnpack = SafeUnpack
    for i, desc in ipairs(descList) do
        local paramsConfig = DescKey2ParamConfig[desc]
        
        if paramsCount > 0 then
            --- 不要通过给i赋值跳过几次循环 防止 DescKey 配成 例：_#buff__#buff_颜色_参数1_参数2_参数3_参数4_ 连续出现两次取第二个
            paramsCount = paramsCount - 1

        elseif paramsConfig == nil then
            table.insert(starDescList, desc)

        else
            local paramType, count = SafeUnpack(paramsConfig)
            paramsCount = count
            ---检查是否是新版技能描述 
            if paramType >= DescParamsType.SkillEffect then
                table.link(starDescList, CardProgressionSkillUtils.FixDesc(paramType, descList, i, star, skillCardVo, finalSkillLevel, lastSkillCardVo))
            else
                local res = CardProgressionSkillUtils.ParseSkillLogicConfPlaceholder(descList, i, skillCardVo, star, paramType, finalSkillLevel, isHideColor, lastSkillCardVo, isFinal)
                if res then
                    table.insert(starDescList, res)
                end
                
            end

        end

    end
    return starDescList
end

---ParseSkillLogicConfPlaceholder
---解析 技能牌逻辑表 占位符
function CardProgressionSkillUtils.ParseSkillLogicConfPlaceholder(descList, i, skillCardVo, star, paramType, finalSkillLevel, isHideColor, lastSkillCardVo, isFinal)
    local colorKey = descList[i + 1]
    local row      = cardConfMgr:GetSkillDescFontColorByKey(colorKey)
    if row == nil then return end
    
    local isCurrentLv = parse_number(row, "isUpLv", 0) == 0

    local targetConf =  SkillPlaceholder2TargetConf[paramType]

    ---@type SkillCardVo
    local realVo = isCurrentLv and skillCardVo or lastSkillCardVo
    local realFinalLv = finalSkillLevel
    if not isCurrentLv and finalSkillLevel then
        realFinalLv = finalSkillLevel - 1
    end

    local isDisableFloor = false
    local totalEffectNum
    if targetConf == TargetConf.DamageType then 
        --- 查找 《伤害类型》
        totalEffectNum = CardProgressionSkillUtils.ParseSkillPlaceholderAtDamageType(descList, i + 1, paramType)
        isDisableFloor = true
    else
        local effectId, skillConfigIndex, skillId = CardProgressionSkillUtils.GetEffectIdAndSkillConfIndex(descList, i, realVo, star)
        local curIndex = i + 4
    
        if targetConf == TargetConf.BuffEffectLevel then
            --- 查找 《BUFF效果升级表》
            totalEffectNum = CardProgressionSkillUtils.ParseSkillPlaceholderAtBuffEffectLevel(descList, curIndex, effectId, star, paramType, realFinalLv)
            
        elseif targetConf == TargetConf.SkillLogicEffectLevel then
            --- 查找 《技能效果升级表》 走公式 大招的话 star  写死1
            totalEffectNum = CardProgressionSkillUtils.ParseSkillPlaceholderAtSkillLogicEffectLevel(descList, curIndex, effectId, isFinal and 1 or star, paramType, skillConfigIndex, realFinalLv)
            
        elseif targetConf == TargetConf.BuffLevel then
            --- 查找 《BUFF升级表》
            totalEffectNum = CardProgressionSkillUtils.ParseSkillPlaceholderAtBuffLevel(descList, curIndex, effectId, star, paramType)
            
        elseif targetConf == TargetConf.SkillLevel then
            --- 查找 《技能升级数据表》
            totalEffectNum = CardProgressionSkillUtils.ParseSkillPlaceholderAtSkillLevel(skillId, skillConfigIndex, star, paramType)
        end

    end

    local isPercent = checkNumber(row:Get("isConversion")) > 0
    local effectNumStr = CardProgressionSkillUtils.HandlePercent(isPercent, totalEffectNum, nil, isDisableFloor, realFinalLv)

    if isHideColor then
        return string.format(effectNumStr)
    else
        return CardProgressionSkillUtils.ReplaceColorPattern(row, effectNumStr)
    end
    
end

---ReplaceColorPattern
---替换颜色匹配符
---@param row TableML.TableFileRow 技能描述字体颜色信息 一行数据
---@param effectNumStr string 
function CardProgressionSkillUtils.ReplaceColorPattern(row, effectNumStr)
    local colorStr     = parse_string(row, "color")
    return tostring(string.gsub(colorStr, "target_num", effectNumStr))
end

---GetEffectIdAndSkillConfIndex
---获取 技能表 效果id 和 下标
---@param descList string[] 描述列表
---@param i number 描述列表 下标
---@param skillCardVo SkillCardVo  技能表vo
---@param star number  技能星级
---@param lastSkillCardVo SkillCardVo 下一技能表vo
function CardProgressionSkillUtils.GetEffectIdAndSkillConfIndex(descList, i, skillCardVo, star)
    ---《技能牌逻辑表》的技能：0、默认技能；1、覆盖技能1；2、覆盖技能2
    local effectFlag       = descList[i + 2]
    ---《技能表》下标，第N个BUFF/技能效果
    local skillConfigIndex = checkNumber(descList[i + 3])

    --- 技能表id
    local skillId = checkNumber(effectFlag) == 0 and skillCardVo.orginSkills[star] or skillCardVo.overSkills[star][checkNumber(effectFlag)]
    ---@type UIBattlingSkillCardVo
    local skillVo = UIBattlingTools.GetSkillCardInfoBySkillId(skillId, star)
    local effectIdName = skillConfigIndex == 0 and "damageEffect" or table.concat({ "effect", skillConfigIndex })
    --- 效果表Id
    local effectId = skillVo[effectIdName]

    if checkNumber(effectId) == 0 then
        printError("解析 技能牌逻辑表 占位符 effectId = 0  ", checkNumber(effectFlag), skillConfigIndex, skillId, star, effectIdName,
            table.dump(checkTable(skillCardVo.overSkills, nil, 3)), 
            table.dump(checkTable(skillCardVo.orginSkills, nil, 3)), 
            table.dump(checkTable(skillVo, nil, 3)))
    end

    return effectId, skillConfigIndex, skillId
end

function CardProgressionSkillUtils.ParseSkillPlaceholderAtBuffEffectLevel(descList, startIndex, buffId, star, paramType, finalSkillLevel)
    if paramType == DescParamsType.Buff then
        ---《BUFF表》里第N个触发效果
        local buffTriggerIndex = checkNumber(descList[startIndex])
        ---《BUFF表》里第N个BUFF效果
        local buffEffectIndex  = checkNumber(descList[startIndex + 1])
        ---《BUFF效果升级表》或《技能效果升级表》里字段“effectNum1”，数组的下标
        local effectLevelIndex  = checkNumber(descList[startIndex + 2])

        local effectId, effectType, buffRow = CardProgressionSkillUtils.GetBuffTriggerData(buffId, buffTriggerIndex, buffEffectIndex, paramType)

        ---buff升级类型（1.正常升级，对应升星表星级；2.公式升级，所有buff效果取1星数据，按公式升级，策划约定只能给只有一个参数的buff用；3.不升级，所有星级均取1星数据，默认1）
        local levelUpType = parse_number(buffRow, "levelUpType", 1)
        star = levelUpType == 1 and star or 1

        local effectUpgradeId = IdConcat(effectId, star)
        local effectUpgrade
        if effectType == 1 then
            --- 如果是 buff效果 则需要去 BUFF效果升级表 找 effectNum1
            effectUpgrade = cardConfMgr:GetBuffEffectUpgradeInfoByRefId(effectUpgradeId)
        elseif effectType == 2 then
            --- 如果是 skill效果 则需要去 技能效果升级表 找 effectNum1
            effectUpgrade = cardConfMgr:GetSkillEffectUpgradeInfoByRefId(effectUpgradeId)
        else
            printError("描述占位符解析只支持 触发类型 是 buff效果 或 技能效果 当前触发类型 = %s", effectType)
        end
        local totalEffectNum = 0
        if effectUpgrade and effectLevelIndex > 0 then
            totalEffectNum = CardProgressionSkillUtils.GetEffectUpgradeEffectNum(effectUpgrade, effectLevelIndex)
            totalEffectNum = totalEffectNum * CardProgressionSkillUtils.CalcBuffFinalSkillEffectAdditionByBuffData(buffRow, finalSkillLevel)
        end

        return totalEffectNum
    end

end

---GetBuffTriggerData
---获取buff 触发数据
---@param buffId number BUFF表id
function CardProgressionSkillUtils.GetBuffTriggerData(buffId, buffTriggerIndex, buffEffectIndex, paramType)
    local buffRow    = cardConfMgr:GetBuffData(buffId)
    local effectType, effectId

    local isEffectUpgradeId = paramType == DescParamsType.Passive or paramType == DescParamsType.Buff
    --- 如果存在buff触发效果
    if buffTriggerIndex > 0 then
        --- 获取 触发类型（1、BUFF效果；2、技能效果；3、被动技能 4、主动技能牌）
        local effectTypes = parse_strings(parse_string(buffRow, "effectType"))
        --- 获取 附加的效果ID(或者技能ID)
        local effectIds   = parse_strings(parse_string(buffRow, "effectId"))

        effectType = checkNumber(effectTypes[buffTriggerIndex])
        effectId   = checkNumber(effectIds[buffTriggerIndex])
        if effectType == 0 or effectId == 0 then
            printError("描述配置了《BUFF表》里第N个触发效果 %s 但是 触发类型 = %s, 附加的效果ID(或者技能ID) = %s 找到不对应配置", buffTriggerIndex, effectType, effectId)
        elseif effectType == 1 then
            --- 更新下 buffRow
            buffRow    = cardConfMgr:GetBuffData(effectId)
            if buffEffectIndex and isEffectUpgradeId then
                effectId = CardProgressionSkillUtils.GetBuffEffectId(buffRow, buffEffectIndex)
            end
        end
        
    elseif buffEffectIndex and isEffectUpgradeId then
        effectType = 1
        buffEffectIndex = buffEffectIndex == 0 and 1 or buffEffectIndex
        effectId   = CardProgressionSkillUtils.GetBuffEffectId(buffRow, buffEffectIndex)

    else
        --- 默认当前传入buff
        effectType = 1
        effectId = buffId

    end

    return effectId, effectType, buffRow

end

function CardProgressionSkillUtils.ParseSkillPlaceholderAtSkillLogicEffectLevel(descList, i, effectId, star, paramType, skillConfigIndex, finalSkillLevel)
    local totalEffectNum = 0
    if DescParamsType.Skill == paramType then
        --- _#skill_颜色_参数1_参数2_参数3_
        local effectLevelIndex = checkNumber(descList[i])
        local effectUpgradeId  = IdConcat(effectId, star)
        --- skill 技能效果升级数据表
        local effectUpgrade   = cardConfMgr:GetSkillEffectUpgradeInfoByRefId(effectUpgradeId)
        if effectUpgrade and effectLevelIndex > 0 then
            totalEffectNum = CardProgressionSkillUtils.GetEffectUpgradeEffectNum(effectUpgrade, effectLevelIndex)
            totalEffectNum = totalEffectNum * CardProgressionSkillUtils.CalcSkillFinalSkillEffectAddition(skillConfigIndex, finalSkillLevel)
        end
    end

    return totalEffectNum

end

function CardProgressionSkillUtils.ParseSkillPlaceholderAtBuffLevel(descList, i, buffId, star, paramType, buffEffectIndex)
    local totalEffectNum   = 0
    -- 《BUFF表》里第N个触发效果
    local buffTriggerIndex = checkNumber(descList[i])
    local effectId, effectType, buffRow         = CardProgressionSkillUtils.GetBuffTriggerData(buffId, buffTriggerIndex, buffEffectIndex, paramType)
    if effectId == 0 then
        return totalEffectNum
    end

    local levelUpType = parse_number(buffRow, "levelUpType", 1)
    star = levelUpType == 1 and star or 1
    
    local buffLevelRow = cardConfMgr:GetBuffUpgradeRow(effectId, star)
    if DescParamsType.Control == paramType then
        totalEffectNum = math.abs(parse_number(buffLevelRow, "crowdControl", 0)) 

    elseif DescParamsType.CoolDown == paramType then
        totalEffectNum = parse_number(buffLevelRow, "triggerCdNum", 0)

    elseif DescParamsType.Round == paramType then
        totalEffectNum = parse_number(buffLevelRow, "round", 0)

    elseif DescParamsType.StackMax == paramType then
        totalEffectNum = parse_number(buffLevelRow, "stackingMax", 0)
        
    end

    return totalEffectNum, buffRow

end

---ParseSkillPlaceholderAtSkillLevel
---@param skillId number 技能表 id
---@param skillLevelConfFieldIndex number 技能升级表字段下标
---@param star number 技能星级
---@param paramType number 参数类型
function CardProgressionSkillUtils.ParseSkillPlaceholderAtSkillLevel(skillId, skillLevelConfFieldIndex, star, paramType)
    local totalEffectNum   = 0
    if DescParamsType.StackTime == paramType then
        local row = cardConfMgr:GetSkillLevelRow(skillId, star)
        if row then
            local headName = string.format("stackTime%s", skillLevelConfFieldIndex == 0 and 1 or skillLevelConfFieldIndex)
            totalEffectNum = parse_number(row, headName, 0)
        end
    end

    return totalEffectNum
end

function CardProgressionSkillUtils.ParseSkillPlaceholderAtDamageType(descList, i, paramType)
    local damageTypeId         = descList[i + 1]
    ---@type DamageTypeVo
    local damageTypeVo = cardConfMgr:GetDamageTypeByRefId(damageTypeId)
    if damageTypeVo == nil then
        return 0
    end

    local damageTypeParamIndex = checkNumber(descList[i + 2])
    local damageRatio = checkNumber(damageTypeVo.damageRatioParams[damageTypeParamIndex])
    return damageRatio == 0 and 1 or damageRatio
end


function CardProgressionSkillUtils.GetBuffEffectId(buffRow, index)
    local effects         = parse_strings(parse_string(buffRow, "effects", ""))
    local buffEffectId    = effects[index]
    return buffEffectId
end


--- FixDesc
---@param paramType number 描述参数类型
---@param descList table 描述列表
---@param index number 描述下标
---@param skillCardVo SkillCardVo  技能表vo
---@param star number 星级
---@param finalSkillLevel number 大招等级
---@param lastSkillCardVo SkillCardVo  技能表vo
function CardProgressionSkillUtils.FixDesc(paramType, descList, index, star, skillCardVo, finalSkillLevel, lastSkillCardVo)
    local t
    if paramType == DescParamsType.SkillEffect then
        t = CardProgressionSkillUtils.FixSkillEffectDesc(descList, index, star, skillCardVo, paramType, finalSkillLevel, lastSkillCardVo)

    elseif paramType == DescParamsType.BuffEffect then
        t = CardProgressionSkillUtils.FixBuffEffectDesc(descList, index, star, paramType, finalSkillLevel)

    elseif paramType == DescParamsType.SkillTarget then
        t = CardProgressionSkillUtils.FixSkillTargetDesc(descList, index, star, skillCardVo)

    elseif paramType == DescParamsType.BuffTarget then
        t = CardProgressionSkillUtils.FixBuffTargetDesc(descList, index)

    elseif paramType == DescParamsType.Limit then
        t = CardProgressionSkillUtils.FixLimitDesc(descList, index)

    end

    return t
end

--- FixSkillEffectDesc
---@param descList table 描述列表
---@param index number 描述下标
---@param skillCardVo SkillCardVo  技能表vo
---@param star number 星级
---@param paramType number 描述参数类型
---@param finalSkillLevel number 大招等级
---@param lastSkillCardVo SkillCardVo  下一级技能表vo
function CardProgressionSkillUtils.FixSkillEffectDesc(descList, index, star, skillCardVo, paramType, finalSkillLevel, lastSkillCardVo)
    local targetId, effectId, skillConfigIndex = CardProgressionSkillUtils.GetTargetIdAndEffectId(descList, index, skillCardVo, star)

    local nextTargetId, nextEffectId
    if lastSkillCardVo then
        nextTargetId, nextEffectId = CardProgressionSkillUtils.GetTargetIdAndEffectId(descList, index, lastSkillCardVo, star + 1)
    end

    --- 其中<target>字段用参数2处取到的目标表ID到《目标表参数表》替代，<para1>和<para2>字段用参数3去升级表找参数替代
    local desc     = cardConfMgr:GetSkillEffectDesc(effectId)
    -- print("FixSkillEffectDesc", desc, "---", targetId, "---", effectId)
    
    ---《技能表》下标，第N个BUFF/技能效果
    local effectUpgradeIndex1 = checkNumber(descList[index + 3])
    local effectUpgradeIndex2 = checkNumber(descList[index + 4])
    
    local t = {}
    local paraStr1 = string.format(ParaFlag, effectUpgradeIndex1)
    local paraStr2 = string.format(ParaFlag, effectUpgradeIndex2)
    strWalk(desc, BracketPattern, function(s, isHit)
        if not isHit then
            table.insert(t, s)
            return
        end

        if s == TargetFlag then
            --- 查找 目标表参数表 
            table.insert(t, cardConfMgr:GetTargetTypeDesc(targetId))
        else
            local isPara1 = string.find(s, paraStr1)
            if isPara1 or string.find(s, paraStr2) then   
                --- paraX_参数1_参数2_参数
                --- 参数1：是否升星。0.不升星；1.读表升星；2.下一星级
                --- 参数2：是否百分比。0.百分比 1.整数 2.正负整数；3.正负百分比
                local paramsList       = string.split(s, "_")
                local starType         = checkNumber(paramsList[2])
                local numStr           = string.gsub(paramsList[3], ">", "")
                local numType          = checkNumber(numStr)
                local isPercent        = numType == 0 or numType == 3
                local realStar         = CardProgressionSkillUtils.FixStarByType(starType, star)
                local realEffectId     = CardProgressionSkillUtils.FixEffectIdByType(starType, effectId, nextEffectId)
                local effectUpgradeId  = string.format("%s_%s",  realEffectId, realStar)
                
                local effectUpgrade    = cardConfMgr:GetSkillEffectUpgradeInfoByRefId(effectUpgradeId)
                --- 查找 技能效果升级表
                local upgradeIndex = isPara1 and effectUpgradeIndex1 or effectUpgradeIndex2
                local totalEffectNum, isPositiveNum = CardProgressionSkillUtils.GetEffectUpgradeEffectNum(effectUpgrade, upgradeIndex)
                totalEffectNum = totalEffectNum * CardProgressionSkillUtils.HandleFinalSkillEffectAddition(finalSkillLevel, paramType, skillConfigIndex, realEffectId)
                totalEffectNum = CardProgressionSkillUtils.HandlePercent(isPercent, totalEffectNum, true)
                
                if numType == 2 or numType == 3 then
                    table.insert(t, isPositiveNum and "+" or "-")
                end
                table.insert(t, totalEffectNum) 
            else
                table.insert(t, s)
            end
        end
        
    end)
    return t
end

--- FixSkillTargetDesc
---@param descList table 描述列表
---@param index number 描述下标
---@param skillCardVo SkillCardVo  技能表vo
---@param star number 星级
function CardProgressionSkillUtils.FixSkillTargetDesc(descList, index, star, skillCardVo)
    local targetId, effectId = CardProgressionSkillUtils.GetTargetIdAndEffectId(descList, index, skillCardVo, star)
    local desc = cardConfMgr:GetSkillEffectTagDesc(effectId)
    -- print("FixSkillTargetDesc", desc, targetId, effectId)
    local t = {}
    strWalk(desc, BracketPattern, function(s, isHit)
        if not isHit then
            table.insert(t, s)
            return
        end
        if s == TargetFlag then
            --- 查找 目标表参数表 
            table.insert(t, cardConfMgr:GetTargetTypeDesc(targetId))
        else
            table.insert(t, s)

        end

    end)
    return t

end

--- GetTargetIdAndEffectId
---@param descList table 描述列表
---@param index number 描述下标
---@param skillCardVo SkillCardVo  技能表vo
---@param star number 星级
---@return number, number 目标id, 效果id
function CardProgressionSkillUtils.GetTargetIdAndEffectId(descList, index, skillCardVo, star)
    ---《技能牌逻辑表》的技能：0、默认技能；1、覆盖技能
    local effectFlag       = checkNumber(descList[index + 1])
    ---《技能表》下标，第N个BUFF/技能效果
    local skillConfigIndex = checkNumber(descList[index + 2])
    --- 技能表id
    local skillId = effectFlag == 1 and skillCardVo.overSkills[star] or skillCardVo.orginSkills[star]
    ---@type UIBattlingSkillCardVo
    local skillVo = UIBattlingTools.GetSkillCardInfoBySkillId(skillId, star)
    local targetIdName = skillConfigIndex == 0 and "damageTarget" or string.format("effectTarget%s", skillConfigIndex)
    --- 目标id
    local targetId = skillVo[targetIdName] < 0 and skillVo.damageTarget or skillVo[targetIdName]

    local effectIdName = skillConfigIndex == 0 and "damageEffect" or string.format("effect%s", skillConfigIndex)
    --- 效果表Id
    local effectId = skillVo[effectIdName]

    return targetId, effectId, skillConfigIndex
end

--- FixBuffEffectDesc
---@param descList table 描述列表
---@param index number 描述下标
---@param skillCardVo SkillCardVo  技能表vo
---@param star number 星级
---@param paramType number 描述参数类型
---@param finalSkillLevel number 大招等级
function CardProgressionSkillUtils.FixBuffEffectDesc(descList, index, star, paramType, finalSkillLevel)
    ---《BUFF效果描述表》ID
    local buffEffectDescId     = checkNumber(descList[index + 1])
    ---《目标表类型表》ID
    local targetId             = checkNumber(descList[index + 2])
    ---《BUFF表》ID
    local buffId               = checkNumber(descList[index + 3])
    ---《BUFF效果表》id
    local buffEffectId         = checkNumber(descList[index + 4])
    ---《BUFF效果升级表》里字段“effectNum1”，数组的下标
    local effectUpgradeIndex1  = checkNumber(descList[index + 5])
    ---《BUFF效果升级表》里字段“effectNum1”，数组的下标
    local effectUpgradeIndex2  = checkNumber(descList[index + 6])

    local desc                        = cardConfMgr:GetBuffEffectDesc(buffEffectDescId)
    -- print("FixBuffEffectDesc", desc, buffEffectDescId)
    local paraStr1 = string.format(ParaFlag, effectUpgradeIndex1)
    local paraStr2 = string.format(ParaFlag, effectUpgradeIndex2)
    local t = {}
    
    strWalk(desc, BracketPattern, function(s, isHit)
        if not isHit then
            table.insert(t, s)
            return
        end

        if s == TargetFlag then
            --- 查找 目标表参数表 
            table.insert(t, cardConfMgr:GetTargetTypeDesc(targetId))
        else
            local isPara1 = string.find(s, paraStr1)
            if isPara1 or string.find(s, paraStr2) then
                local upgradeIndex     = isPara1 and effectUpgradeIndex1 or effectUpgradeIndex2
                -- print("upgradeIndex", upgradeIndex, s)
                --- paramsList[1]_paramsList[2]_paramsList[3]
                --- paraX_参数1_参数2
                --- 参数1：是否升星。0.不升星；1.读表升星；2.下一星级
                --- 参数2：是否百分比。0.百分比 1.整数 2.正负整数；3.正负百分比
                
                local paramsList       = string.split(s, "_")
                local starType         = checkNumber(paramsList[2])
                local numStr           = string.gsub(paramsList[3], ">", "")
                local numType          = checkNumber(numStr)
                local isPercent        = numType == 0 or numType == 3
                
                local realStar         = CardProgressionSkillUtils.FixStarByType(starType, star)
                local effectUpgradeRow = cardConfMgr:GetBuffEffectUpgradeInfoByBuffEffectId(buffEffectId, realStar) 
                local totalEffectNum, isPositiveNum   = CardProgressionSkillUtils.GetEffectUpgradeEffectNum(effectUpgradeRow, upgradeIndex)
                totalEffectNum         = totalEffectNum * CardProgressionSkillUtils.HandleFinalSkillEffectAddition(finalSkillLevel, paramType, nil, buffId)
                totalEffectNum         = CardProgressionSkillUtils.HandlePercent(isPercent, totalEffectNum, true)

                if numType == 2 or numType == 3 then
                    table.insert(t, isPositiveNum and "+" or "-")
                end
                table.insert(t, totalEffectNum)
                
            elseif string.find(s, RoundFlag) then
                --- <round_参数1>
                --- 参数1：是否升星。0.不升星；1.读表升星；2.下一星级
                -- local buffUpgradeId = 
                local paramsList       = string.split(s, "_")
                local starTypeStr      = string.gsub(paramsList[2], ">", "")
                local starType         = checkNumber(starTypeStr)
                local realStar         = CardProgressionSkillUtils.FixStarByType(starType, star)
                local buffUpgradeRow   = cardConfMgr:GetBuffUpgradeRow(buffId, realStar)
                local round            =  parse_number(buffUpgradeRow, "round", 0)
                table.insert(t, round)
    
            else
                table.insert(t, s)
    
            end
        end
        
    end)
    return t
end

--- FixBuffTargetDesc
---@param descList table 描述列表
---@param index number 描述下标
function CardProgressionSkillUtils.FixBuffTargetDesc(descList, index)
    ---《BUFF效果描述表》ID
    local buffEffectDescId = checkNumber(descList[index + 1])
    local desc             = cardConfMgr:GetBuffTagDesc(buffEffectDescId)
    return {desc}

end

--- FixLimitDesc
---@param descList table 描述列表
function CardProgressionSkillUtils.FixLimitDesc(descList, index)
    ---《被动技能生效场合枚举表》Id
    local id = checkNumber(descList[index + 1])
    ---@type BuffEffectOccasionVo
    local vo = cardConfMgr:GetBuffEffectOccasionVo(id)
    return {vo.desc}
end

--- FixBuffTargetDesc
---@param starType number 星级类型
---@param star number 星级
function CardProgressionSkillUtils.FixStarByType(starType, star)
    local realStar
    if starType == StarType.ReadConf then
        realStar = star
    elseif starType == StarType.Next then
        realStar = star + 1
    else
        realStar = 1
    end
    return realStar
end

--- FixEffectIdByType
---@param starType number 星级类型
---@param effectId number 效果id
---@param nextEffectId number 下一级效果id
function CardProgressionSkillUtils.FixEffectIdByType(starType, effectId, nextEffectId)
    if starType == StarType.Next then
        if nextEffectId == nil then
            printError("传入参数错误 未找到 nextEffectId")
            return effectId
        end
        return nextEffectId
    end
    return effectId
end

--- FixBuffTargetDesc
---@param isPercent boolean 是否是百分比
---@param totalEffectNum number 效果数值
function CardProgressionSkillUtils.HandlePercent(isPercent, totalEffectNum, isSingle, isDisableFloor, finalSkillLevel)
    local effectNumStr
    if isPercent then
        local isFinal = finalSkillLevel ~= nil and finalSkillLevel > 0
        local num = isFinal and num_floor(totalEffectNum * 100) or (checkInt(totalEffectNum * 10000) / 100)
        local percentSign = isSingle and SinglePercentSignPattern or DoublePercentSignPattern
        effectNumStr = string.format(percentSign, num)
    else
        if isDisableFloor then
            return tostring(totalEffectNum)
        end
        local num = math.floor(totalEffectNum)
        effectNumStr = tostring(num)
    end
    return effectNumStr
end

--- FixBuffEffectDesc
---@param finalSkillLevel number 大招等级
---@param paramType number 描述参数类型
---@param skillConfigIndex number  技能表下标
---@param buffId number buff表id
function CardProgressionSkillUtils.HandleFinalSkillEffectAddition(finalSkillLevel, paramType, skillConfigIndex, buffId)
    local factor = 1
    if finalSkillLevel and finalSkillLevel > 0 then
        -- 如果是大招，要判断是否使用公式计算升级数据
        if paramType == DescParamsType.Buff or paramType == DescParamsType.BuffEffect then
            factor = CardProgressionSkillUtils.CalcBuffFinalSkillEffectAdditionByBuffId(buffId, finalSkillLevel)
        elseif (paramType == DescParamsType.Skill or paramType == DescParamsType.SkillEffect) and skillConfigIndex == 0 then
            -- 技能只有主效果按公式升级
            factor = CardProgressionSkillUtils.CalcSkillFinalSkillEffectAddition(skillConfigIndex, finalSkillLevel)
        end
    end
    return factor
end


---CalcBuffFinalSkillEffectAdditionByBuffId
---通过 buffId 计算buff效果 大招等级加成
function CardProgressionSkillUtils.CalcBuffFinalSkillEffectAdditionByBuffId(buffId, finalSkillLevel)
    local buffData = cardConfMgr:GetBuffData(buffId)
    return  CardProgressionSkillUtils.CalcBuffFinalSkillEffectAdditionByBuffData(buffData, finalSkillLevel)
end

---CalcBuffFinalSkillEffectAdditionByBuffData
---通过 buffData 计算buff效果 大招等级加成
---@param buffData TableML.TableFileRow buff表 一行数据
---@param finalSkillLevel number 大招等级
function CardProgressionSkillUtils.CalcBuffFinalSkillEffectAdditionByBuffData(buffData, finalSkillLevel)
    -- buff读表看升级类型，类型2表示使用公式升级
    local levelUpType = parse_number(buffData, "levelUpType", 1)
    if levelUpType == 2 and finalSkillLevel and finalSkillLevel > 0 then
        return cardConfMgr:GetFinalSkillUpParams(finalSkillLevel)
    end
    return 1
end

---CalcSkillFinalSkillEffectAddition
---通过 技能表下标（0：主效果） 计算技能效果 大招等级加成
---@param skillConfigIndex number 技能表下标（0：主效果）
---@param finalSkillLevel number 大招等级
function CardProgressionSkillUtils.CalcSkillFinalSkillEffectAddition(skillConfigIndex, finalSkillLevel)
    ---主效果才计算大招加成
    if skillConfigIndex == 0 and finalSkillLevel and finalSkillLevel > 0 then 
        return cardConfMgr:GetFinalSkillUpParams(finalSkillLevel)
    end

    return 1
end

--- GetEffectUpgradeEffectNum
---@param effectUpgrade TableML.TableFileRow 效果升级数据信息 
---@param index number 效果数值下标
function CardProgressionSkillUtils.GetEffectUpgradeEffectNum(effectUpgrade, index)
    local effectNumList = parse_strings(parse_string(effectUpgrade, "effectNum1"), ";")
    local starEffectNum = checkNumber(effectNumList[index])
    local isPositiveNum = starEffectNum >= 0
    return math.abs(starEffectNum), isPositiveNum
end

---GetCardTalentDesc
---@param id number 角色天赋表id
---@param lastSkillId number 角色天赋表上一级id
function CardProgressionSkillUtils.GetCardTalentDescById(id, skillLevel, lastSkillId, desc)
    ---@type TalentVo | SkillCardVo
    local vo = CardProgressionSkillUtils.GetSkillVoBySkillGroupType(id, CardProgressionConstants.SkillGroupType.Buff)

    ---@type TalentVo | SkillCardVo
    local lastVo
    if lastSkillId then
        lastVo = CardProgressionSkillUtils.GetSkillVoBySkillGroupType(lastSkillId, CardProgressionConstants.SkillGroupType.Buff)
    end

    local desc = CardProgressionSkillUtils.GetCardTalentDesc(vo, skillLevel, lastVo, desc)
    local realVo = vo
    return desc, realVo.name, realVo

end

---GetCardTalentDesc
---@param vo TalentVo
function CardProgressionSkillUtils.GetCardTalentDesc(vo, skillLevel, lastVo, desc)
    return CardProgressionSkillUtils.ParseCardTalentDesc(desc or vo.desc, skillLevel, vo, lastVo)
end

function CardProgressionSkillUtils.ParseCardTalentDesc(desc, skillLevel, vo, lastVo)
    local descList = string.split2(desc, "_")
    local paramsCount = 0
    local realDescList = {}
    for i, desc in ipairs(descList) do
        local paramsConfig = DescKey2ParamConfig[desc]
        
        if paramsCount > 0 then
            --- 不要通过给i赋值跳过几次循环 防止 DescKey 配成 例：_#buff__#buff_颜色_参数1_参数2_参数3_参数4_ 连续出现两次取第二个
            paramsCount = paramsCount - 1

        elseif paramsConfig == nil then
            table.insert(realDescList, desc)
        else
            local paramType, count = SafeUnpack(paramsConfig)
            paramsCount = count
            if paramType >= DescParamsType.SkillEffect then
                table.link(realDescList, CardProgressionSkillUtils.FixDesc(paramType, descList, i, skillLevel))
            else
                table.insert(realDescList, CardProgressionSkillUtils.ParseBuffPlaceholder(paramType, descList, i, vo, skillLevel, lastVo))
            end
                
        end
    end

    local result
    if CardProgressionSkillUtils.SkillExtraMode then
        result = table.concat(realDescList)
    else
        result = string.gsub(table.concat(realDescList), "\\n", "\n")
    end

    return result
end

---ParseBuffPlaceholder
---@param vo TalentVo
function CardProgressionSkillUtils.ParseBuffPlaceholder(paramType, descList, i, vo, skillLevel, lastVo)
    local colorKey = descList[i + 1]
    local row      = cardConfMgr:GetSkillDescFontColorByKey(colorKey)
    if row == nil then return end
    --  0：当前等级的猫球技能
    --  1：上一等级的猫球技能
    local isCurrentLv = parse_number(row, "isUpLv", 0) == 0
    -- 《角色天赋表》的addSkillId下标
    local addSkillIndex = checkNumber(descList[i + 2])

    local realVo        = isCurrentLv and vo or lastVo
    local passive       = realVo.passive[addSkillIndex]
    local buffId        = passive.id
    local buffStar      = passive.num

    local totalEffectNum
    local targetConfType = BuffPlaceholder2TargetConf[paramType]
    local curIndex       = i + 3
    if targetConfType == TargetConf.BuffEffectLevel then
        totalEffectNum = CardProgressionSkillUtils.ParseBuffPlaceholderAtBuffEffectLevel(paramType, descList, curIndex, buffId, buffStar)

    elseif targetConfType == TargetConf.BuffLevel then
        totalEffectNum = CardProgressionSkillUtils.ParseBuffPlaceholderAtBuffLevel(paramType, descList, curIndex, buffId, buffStar)
    end

    local isPercent = checkNumber(row:Get("isConversion")) > 0
    local effectStr = CardProgressionSkillUtils.HandlePercent(isPercent, totalEffectNum)

    return CardProgressionSkillUtils.ReplaceColorPattern(row, effectStr)
    
end

function CardProgressionSkillUtils.ParseBuffPlaceholderAtBuffEffectLevel(paramType, descList, i, buffId, buffStar, finalSkillLv)
    local totalEffectNum   = 0
    if paramType == DescParamsType.Passive or paramType == DescParamsType.Num then
        totalEffectNum = CardProgressionSkillUtils.ParseSkillPlaceholderAtBuffEffectLevel(descList, i, buffId, buffStar, DescParamsType.Buff, finalSkillLv)
    end

    return totalEffectNum
end

function CardProgressionSkillUtils.ParseBuffPlaceholderAtBuffLevel(paramType, descList, i, buffId, buffStar)
    ---《BUFF表》里第N个BUFF效果
    local buffEffectIndex = checkNumber(descList[i])
    local curIndex = i + 1
    return CardProgressionSkillUtils.ParseSkillPlaceholderAtBuffLevel(descList, curIndex, buffId, buffStar, paramType, buffEffectIndex)

end

---ParseSkillOtherDesc
---解析技能附加描述
---@param skillCardVo    SkillCardVo  技能表vo
---@param skillGroupType CardProgressionConstants.SkillGroupType 技能组类型
function CardProgressionSkillUtils.ParseSkillOtherDesc(skillCardVo, skillGroupType)
    local startSkillStar, endSkillStar = 1, 1
    if skillGroupType == CardProgressionConstants.SkillGroupType.Normal then
        local skillId = skillCardVo.orginSkills[1] or skillCardVo.overSkills[1]
        ---@type UIBattlingSkillCardVo
        local skillVo = UIBattlingTools.GetSkillCardInfoBySkillId(skillId, 1)
        endSkillStar = skillVo.skillStarMax
    end
    local otherDescInfo = {}
    local descOther = skillCardVo.descOther or ParseLocalizeText(skillCardVo, "descOther", '')
    if string.isEmpty(descOther) or descOther == "0" then
        return otherDescInfo
    end
    local starBuffIdList = string.slice(descOther, ";")
    for star = startSkillStar, endSkillStar do
        local starBuffId = starBuffIdList[star]
        if not string.isEmpty(starBuffId) then
            otherDescInfo[star] = otherDescInfo[star] or {}
            local buffIdList = string.slice(starBuffId, ",")
            for i, buffId in ipairs(buffIdList) do
                otherDescInfo[star] = otherDescInfo[star] or {}
                local name, skillDesc = CardProgressionSkillUtils.ParseSkillBuffDesc(buffId, star)
                -- local row = cardConfMgr:GetSkillBuffDescByRefId(buffId)
                -- local name = parse_localizeText(row, "name")
                -- local skillDesc = parse_localizeText(row, "skillDesc", true, StrEmpty)
                table.insert(otherDescInfo[star], { name = name, skillDesc = skillDesc })
            end
        end
    end

    return otherDescInfo
end

--- ParseOtherDesc
---@param buffIdListStr string 
function CardProgressionSkillUtils.ParseOtherDesc(buffIdListStr)
    local otherDescInfo = {}
    if string.isEmpty(buffIdListStr) then
        return otherDescInfo
    end
    local buffIdList = string.slice(buffIdListStr, ";")
    
    for i, buffId in ipairs(buffIdList) do
        local titleName, skillDesc = CardProgressionSkillUtils.ParseSkillBuffDesc(buffId)
        table.insert(otherDescInfo, { name = titleName, skillDesc = skillDesc })
    end
    return otherDescInfo
end

function CardProgressionSkillUtils.ParseSkillBuffDesc(buffId, star, finalSkillLv)
--     根据BUFFID在《BUFF表》中查找对应ID下的showDesc，同星级的多个标签通过，分割。不同星级的showDesc描述通过；分割，如果当前星级的描述ID为空则查找上一星级的描述ID，全为空则不显示
--     例如：1;2;3  则1、2、3星分别显示ID为1、2、3的BUFF的描述
--     1.    则1、2、3星全部显示ID为1的BUFF的描述
--     2;3    则1、2、3星分别显示ID为2、3、3的BUFF的描述
--     1,2;3;4 则1、2、3星分别显示ID为1和2、3、4的BUFF的描述

    ---buff表 数据
    local buffData = cardConfMgr:GetBuffData(buffId)
    --- 获取描述id
    local skillBuffDescId = parse_number(buffData, "showDesc") 
    if skillBuffDescId == 0 then
        return StrEmpty, StrEmpty
    end

    local buffDescRow = cardConfMgr:GetSkillBuffDescByRefId(skillBuffDescId)
    if buffDescRow == nil then
        return StrEmpty, StrEmpty
    end
    local titleName = parse_localizeText(buffDescRow, "name",      false, StrEmpty)
    local skillDesc = parse_localizeText(buffDescRow, "skillDesc", true, StrEmpty)
    -- print("skillDesc", skillBuffDescId,  skillDesc)
    if string.isEmpty(skillDesc) then
        return titleName, skillDesc
    end

    --- 不传默认技能1星
    star = star or 1

    --- skillDesc -> 攻击力提升_num_1_1_
    --- 获取由"_"分割后的数据
    local paramsCount = 0
    local descList = string.split2(skillDesc, "_")
    local realDescList = {}
    for i, desc in ipairs(descList) do
        local paramsConfig = DescKey2ParamConfig[desc]
        if paramsCount > 0 then
            paramsCount = paramsCount - 1

        elseif paramsConfig == nil then
            table.insert(realDescList, desc)

        else
            local paramType, count = SafeUnpack(paramsConfig)
            paramsCount = count

            local colorKey = descList[i + 1]
            local row      = cardConfMgr:GetSkillDescFontColorByKey(colorKey)
            if row then 
                local effectNum = 0
                if paramType == DescParamsType.Num then
                    effectNum = CardProgressionSkillUtils.ParseBuffPlaceholderAtBuffEffectLevel(paramType, descList, i + 2, buffId, star, finalSkillLv)
                end
                local isPercent = checkNumber(row:Get("isConversion")) > 0
                local effectNumStr = CardProgressionSkillUtils.HandlePercent(isPercent, effectNum, nil, nil, finalSkillLv)
                local desc = CardProgressionSkillUtils.ReplaceColorPattern(row, effectNumStr)
                table.insert(realDescList, desc)
            end

        end
    end
    
    return titleName, table.concat(realDescList)

end

--- GetEffectiveTalentOtherDesc
--- 获取有效的天赋其他描述
---@param cardId number 卡牌id
function CardProgressionSkillUtils.GetEffectiveTalentDescInfo(cardId, awakeLv)
    local descOther, desc

    while awakeLv > 0 and (desc == nil or descOther == nil) do
        ---@type TalentVo 
        local vo = CardProgressionSkillUtils.GetTalentVo(cardId, awakeLv)
        if vo then
            if desc == nil then
                desc = CardProgressionSkillUtils.GetCardTalentDesc(vo, awakeLv)
            end
            if not string.isEmpty(vo.descOther) then
                descOther = vo.descOther
            end
        end
        awakeLv = awakeLv - 1

    end
    
    return desc, descOther
end

---GetAllTalentDescInfo
---获取所有的天赋描述信息
---@param cardId number 卡牌id
---@param maxLv number 卡牌最大buff等级
---@param curLv number 卡牌当前buff等级
function CardProgressionSkillUtils.GetAllTalentDescInfo(cardId, maxLv, curLv)
    local t = {}
    local desc, descOther
    for lv = 1, maxLv do
        ---@type TalentVo 
        local vo = CardProgressionSkillUtils.GetTalentVo(cardId, lv)
        if vo then
            desc = CardProgressionSkillUtils.GetCardTalentDesc(vo, lv)
            
            t[lv] = lv > curLv and CardProgressionSkillUtils.ClearColor(desc) or desc
            
            if not string.isEmpty(vo.descOther) and lv <= curLv then
                descOther = vo.descOther
            end
        end
    end
    return t, descOther
end

function CardProgressionSkillUtils.ClearColor(skillDesc)
    return string.gsub(skillDesc, BracketPattern, '')
end

