--- GetCardSkillAttrIcon
---@param showLabel Constants.SkillLabel 技能标签
---@param attributeId Constants.CardAttrType 属性类型
---@param isSmall boolean 是否是小icon
---@param isAoe boolean 是否是 AOE 技能
function CardProgressionSkillUtils.GetCardSkillAttrIcon(showLabel, attributeId, isSmall, isAoe)
    local SkillPropertyColor = CardProgressionConstants.SkillPropertyColor

    local SkillLabel = Constants.SkillLabel
    local condition = showLabel >= SkillLabel.Buff and showLabel <= SkillLabel.AttackAndDebuff and checkNumber(isAoe) > 0
    local name = condition and CardProgressionConstants.SkillTypeAOEIconName[showLabel] or CardProgressionConstants.SkillAttackAttrName[showLabel]
    name = checkString(name)
    
    local color
    if showLabel == SkillLabel.Attack then
        color = SkillPropertyColor[checkNumber(attributeId)] or SkillPropertyColor[-1]
    else
        color = SkillPropertyColor[-1]
    end

    if string.isEmpty(name) then return "", color end
    local path = isSmall and string.format("UIAtlas/CultivateOversea/AttributeIcon/%s_2.png", name) or string.format("UIAtlas/CultivateOversea/AttributeIcon/%s.png", name)
    return path, color
end

