function CardProgressionSkillUtils.GetFullStarSkillTypeData(cardId, star)
    local t = CardProgressionSkillUtils.CollectionUpStarSkillDataList(cardId, star)
    table.sort(t, function(a, b) 
        local aSkillType = a.skillType
        local bSkillType = b.skillType
        local aIsSkillStarType = aSkillType == CardProgressionConstants.SkillType.Star
        local bIsSkillStarType = bSkillType == CardProgressionConstants.SkillType.Star
        if aSkillType ~= bSkillType then
            local aPriority = aIsSkillStarType and 0 or (aSkillType == CardProgressionConstants.SkillType.Final and 2 or 1)
            local bPriority = bIsSkillStarType and 0 or (bSkillType == CardProgressionConstants.SkillType.Final and 2 or 1)
            return aPriority > bPriority
        end

        if aIsSkillStarType ~= bIsSkillStarType then
            return aSkillType < bSkillType
        end

        return a.star < b.star

    end)
    return t
end

function CardProgressionSkillUtils.CollectionUpStarSkillDataList(cardId, star)
    local t          = {}
    local starIds    = cardConfMgr:GetCardStarIds(cardId)

    local isNeedSetSp      = true
    local isNeedSetPassive = true
    for index = #starIds, 1, -1 do
        local starId = starIds[index]
        local star_  = index - 1
        if star >= star_ then
            ---@type CardStarVo
            local starVo          = cardConfMgr:GetCardStarVo(starId)
            local spLevel         = starVo.spLevel
            local skillType       = starVo.skillType
            local passiveLevel    = starVo.passiveLevel
            local initOpenAbility = starVo.initOpenAbility  
            
            if spLevel > 0 and isNeedSetSp then
                table.insert(t, {
                    skillType = CardProgressionConstants.SkillType.Final, 
                    star      = star_,
                    starVo    = starVo,
                    displayLv = cardConfMgr:GetFinalSkillDisplayLevel(spLevel),
                })

                isNeedSetSp = false
            end

            if passiveLevel > 0 and isNeedSetPassive then
                table.insert(t, {
                    skillType = CardProgressionConstants.SkillType.Buff, 
                    star      = star_,
                    starVo    = starVo
                })

                isNeedSetPassive = false
            end

            if skillType == CardProgressionConstants.SkillType.Star and initOpenAbility > 0 then
                table.insert(t, {
                    skillType = CardProgressionConstants.SkillType.Star, 
                    star      = star_,
                    starVo    = starVo
                })
                
            end 

        end
    end
    return t
end


---GetUpStarSkillDataList
---获取升级技能数据列表
function CardProgressionSkillUtils.GetUpStarSkillDataList(cardId, star)
    local t          = CardProgressionSkillUtils.CollectionUpStarSkillDataList(cardId, star)

    table.sort(t, function(a, b) 
        local aSkillType = a.skillType
        local bSkillType = b.skillType
        local aIsSkillStarType = aSkillType == CardProgressionConstants.SkillType.Star
        local bIsSkillStarType = bSkillType == CardProgressionConstants.SkillType.Star
        if aSkillType ~= bSkillType then
            local aPriority = aIsSkillStarType and 2 or (aSkillType == CardProgressionConstants.SkillType.Final and 1 or 0)
            local bPriority = bIsSkillStarType and 2 or (bSkillType == CardProgressionConstants.SkillType.Final and 1 or 0)
            return aPriority > bPriority
        end

        if aIsSkillStarType ~= bIsSkillStarType then
            return aSkillType < bSkillType
        end

        return a.star < b.star

    end)

    return t

end

---GetStarUpSkillDataList
---获取星级技能列表
function CardProgressionSkillUtils.GetStarUpSkillDataList(cardId, star, isFull)
    if isFull then
        return CardProgressionSkillUtils.GetUpStarSkillDataList(cardId, star)
    end
    local starIds = cardConfMgr:GetCardStarIdList(cardId)
    local starId  = starIds[star]
    ---@type CardStarVo
    local starVo          = cardConfMgr:GetCardStarVo(starId)
    local spLevel         = starVo.spLevel
    local skillType       = starVo.skillType
    local passiveLevel    = starVo.passiveLevel
    local initOpenAbility = starVo.initOpenAbility  
    local t = {}
    if spLevel > 0 then
        table.insert(t, {
            skillType = CardProgressionConstants.SkillType.Final, 
            star      = star,
            starVo    = starVo,
            displayLv = cardConfMgr:GetFinalSkillDisplayLevel(spLevel),
        })

    end

    if passiveLevel > 0 then
        table.insert(t, {
            skillType = CardProgressionConstants.SkillType.Buff, 
            star      = star,
            starVo    = starVo
        })

    end

    if skillType == CardProgressionConstants.SkillType.Star and initOpenAbility > 0 then
        table.insert(t, {
            skillType = CardProgressionConstants.SkillType.Star, 
            star      = star,
            starVo    = starVo
        })
        
    end 

    return t
end

---GetFinalSkillLvAndBuffLv
---获取大招等级和被动等级
---@param cardId number 卡牌id
---@param star number 卡牌星级
function CardProgressionSkillUtils.GetFinalSkillLvAndBuffLv(cardId, star)
    local starIds    = cardConfMgr:GetCardStarIds(cardId)

    local finalSkillLv = nil
    local buffSkillLv = nil
    for index = #starIds, 1, -1 do
        local starId = starIds[index]
        local star_  = index - 1
        if star >= star_ then
            ---@type CardStarVo
            local starVo          = cardConfMgr:GetCardStarVo(starId)
            local spLevel         = starVo.spLevel
            local passiveLevel    = starVo.passiveLevel
            
            if finalSkillLv == nil and spLevel > 0 then
                finalSkillLv = cardConfMgr:GetFinalSkillDisplayLevel(spLevel)
            end

            if buffSkillLv == nil and passiveLevel > 0 then
                buffSkillLv = passiveLevel
            end

            if buffSkillLv and finalSkillLv then
                break
            end
        end
    end
    return finalSkillLv, buffSkillLv
end

---ConvertFinalSkillLvByRare
---将CardDojo的大招等级转换成 大招升级参数表 的id
function CardProgressionSkillUtils.ConvertFinalSkillLvByRare(rare, lv)
    local maxDisplayLv = cardConfMgr:GetMaxFinalSkillLv()
    return lv + maxDisplayLv * (rare - 1)
end

return CardProgressionSkillUtils